from __future__ import annotations

from collections import Counter
from html import escape
from pathlib import Path

from .dossier import build_dossier
from .models import MarketEvent
from .worlddeep import WorldLeadAssessment, load_assessments
from .worldscan import GapCandidate, WorldScanStats

CSS = """
:root{color-scheme:dark;--bg:#071019;--panel:#0e1823;--line:#223247;--text:#edf5fb;--muted:#91a2b5;--accent:#6ad7ff;--green:#72e5b6;--yellow:#ffd36b;--purple:#bba7ff}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 18% 0,#102b40 0,var(--bg) 34%);color:var(--text);font:15px/1.55 Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}main{max-width:1320px;margin:auto;padding:38px 24px 80px}.topbar{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.eyebrow{color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.16em;text-transform:uppercase}h1{font-size:clamp(42px,7vw,76px);line-height:.96;margin:10px 0 15px;letter-spacing:-.055em}.lede{max-width:900px;color:#b8c6d5;font-size:17px;margin:0}.pulse{padding:8px 12px;border:1px solid #294057;border-radius:999px;color:#cdefff;background:#0d1b27;white-space:nowrap}.pulse:before{content:'●';color:var(--green);margin-right:7px}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:11px;margin:26px 0}.metric,.sector,.step{padding:17px;background:rgba(14,24,35,.9);border:1px solid var(--line);border-radius:17px}.metric strong,.step b{display:block;font-size:29px}.metric span,.step span{color:var(--muted);font-size:11px;letter-spacing:.08em;text-transform:uppercase}.section{margin-top:34px}.section-head{display:flex;justify-content:space-between;align-items:end;gap:18px;margin-bottom:13px}.section-head h2{margin:2px 0 0;font-size:25px}.section-head p{margin:0;color:var(--muted);max-width:700px}.sector-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.sector strong{display:block;font-size:17px}.sector .heat{color:var(--yellow);font-size:13px;margin-top:4px}.sector small{color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.card{background:linear-gradient(180deg,rgba(17,29,42,.96),rgba(10,18,27,.96));border:1px solid var(--line);border-radius:20px;padding:21px}.card.review{border-color:#376d5c}.card.dismiss{opacity:.66}.card h3{margin:11px 0 7px;font-size:20px;line-height:1.28}.meta,.small,.summary{color:var(--muted)}.badges{display:flex;flex-wrap:wrap;gap:6px}.badge{padding:4px 8px;border:1px solid #33475d;border-radius:999px;font-size:10px;text-transform:uppercase;letter-spacing:.06em;color:#c8d6e5}.badge.review{background:var(--green);border-color:var(--green);color:#07120e;font-weight:800}.badge.watch{background:var(--yellow);border-color:var(--yellow);color:#1d1600;font-weight:800}.badge.dismiss{background:#354251;border-color:#354251;font-weight:800}.badge.signal{color:var(--accent);border-color:#315b73}.badge.sector{color:var(--purple);border-color:#564d78}.block{margin-top:14px;padding:13px;border:1px solid #233247;border-radius:13px;background:#09121b}.block h4{margin:0 0 6px;color:#d8e5ef;font-size:11px;text-transform:uppercase;letter-spacing:.08em}.block p{margin:0;color:#aebcca}.block.reco{border-color:#315a4f;background:#0a1715}.block.supply{border-color:#51476d;background:#12101c}.evidence{margin-top:13px;display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;font-size:12px}a{color:var(--accent);text-decoration:none}.funnel{display:grid;grid-template-columns:repeat(6,1fr);gap:9px}.empty{padding:26px;border:1px dashed #334153;border-radius:17px;color:var(--muted)}details{margin-top:28px;border-top:1px solid var(--line);padding-top:18px}summary{cursor:pointer;color:#aebcca;font-weight:700}.footer{margin-top:36px;color:#66798d;font-size:12px}@media(max-width:1000px){.sector-grid,.funnel{grid-template-columns:repeat(2,1fr)}}@media(max-width:820px){.grid{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}.topbar,.section-head{flex-direction:column;align-items:flex-start}}@media(max-width:520px){.sector-grid,.funnel{grid-template-columns:1fr}}
"""

def _badge_class(value: str) -> str:
    return "review" if value == "REVIEW" else "watch" if value == "WATCH" else "dismiss"

def _assessment_card(c: GapCandidate, a: WorldLeadAssessment) -> str:
    ev = a.supply_evidence[:3]
    ev_html = "<br>".join(f'<a href="{escape(str(x.get("url") or "#"))}" target="_blank">{escape(str(x.get("title") or x.get("source") or "evidence"))}</a>' for x in ev) or "No qualifying supply evidence in checked sources."
    coverage = f"checked: {', '.join(a.supply_sources_checked) or 'none'}"
    if a.supply_sources_missing: coverage += f" · missing: {', '.join(a.supply_sources_missing)}"
    return f'''<article class="card {a.final_recommendation.lower()}"><div class="badges"><span class="badge {_badge_class(a.final_recommendation)}">{escape(a.final_recommendation)}</span><span class="badge signal">{escape(a.gap_assessment)}</span><span class="badge sector">{escape(c.sector)}</span></div><h3>{escape(c.headline)}</h3><div class="meta">{escape(c.source)} · {escape(c.published_at or 'time unavailable')}</div><div class="block reco"><h4>Why this may matter</h4><p><b>Change:</b> {escape(c.why_now)}<br><br><b>Demand hypothesis:</b> {escape(c.gap_hypothesis)}</p></div><div class="block supply"><h4>Supply map + judgement</h4><p><b>{escape(a.supply_status)}</b> · {a.supply_candidate_count} candidates scanned<br><b>Coverage:</b> {escape(a.supply_coverage)} · {escape(coverage)}<br><br>{escape(a.summary)}</p></div><div class="block"><h4>Evidence surfaced</h4><p>{ev_html}</p></div><div class="evidence"><span class="small">{escape(a.ecosystem)} · {escape(c.validation_status)}</span><a href="{escape(c.url)}" target="_blank">source ↗</a></div></article>'''

def _candidate_card(c: GapCandidate) -> str:
    return f'''<article class="card"><div class="badges"><span class="badge watch">INVESTIGATING</span><span class="badge sector">{escape(c.sector)}</span><span class="badge signal">{escape(c.change_type.replace('_',' '))}</span></div><h3>{escape(c.headline)}</h3><div class="meta">{escape(c.source)} · {escape(c.published_at or 'time unavailable')}</div><p class="summary">{escape((c.summary or 'No feed summary supplied.')[:520])}</p><div class="block"><h4>Status</h4><p>{escape(c.validation_summary)}</p></div><div class="evidence"><span class="small">signal: {escape(c.matched_signal)}</span><a href="{escape(c.url)}" target="_blank">source ↗</a></div></article>'''

def _verified_card(e: MarketEvent) -> str:
    d=build_dossier(e); official=e.official_evidence[0] if e.official_evidence else None; link=f'<a href="{escape(str(official.url))}" target="_blank">official ↗</a>' if official else "no official source"; h=e.demand_hypothesis.job_to_be_done if e.demand_hypothesis else "Demand hypothesis unavailable."
    return f'''<article class="card"><div class="badges"><span class="badge review">TIER-1 VERIFIED</span><span class="badge signal">{escape(e.gap_status)}</span></div><h3>{escape(e.headline)}</h3><div class="meta">{escape(e.vendor)} · {escape(e.product)}</div><div class="block reco"><h4>Demand hypothesis</h4><p>{escape(h)}</p></div><div class="block supply"><h4>Conclusion</h4><p>{escape(d.verdict)} — {escape(d.rationale)}</p></div><div class="evidence"><span class="small">Reaction {len(e.reaction_evidence)} · Supply {len(e.supply_evidence)}</span>{link}</div></article>'''

def render_dashboard(events: list[MarketEvent], output: Path, world_candidates: list[GapCandidate] | None=None, scan_stats: WorldScanStats | None=None) -> None:
    output.parent.mkdir(parents=True, exist_ok=True); world_candidates=world_candidates or []; assessments=load_assessments(Path("data/world-assessments.json")); by_id={a.candidate_id:a for a in assessments}; pairs=[(c,by_id[c.id]) for c in world_candidates if c.id in by_id]; order={"REVIEW":0,"WATCH":1,"DISMISS":2}; pairs.sort(key=lambda x:(order.get(x[1].final_recommendation,9),x[0].published_at or "")); unresolved=[c for c in world_candidates if c.id not in by_id]
    review=sum(a.final_recommendation=="REVIEW" for _,a in pairs); watch=sum(a.final_recommendation=="WATCH" for _,a in pairs); dismiss=sum(a.final_recommendation=="DISMISS" for _,a in pairs)
    sector_counts=Counter(c.sector for c in world_candidates); sector_reviews=Counter(c.sector for c,a in pairs if a.final_recommendation=="REVIEW"); sector_watches=Counter(c.sector for c,a in pairs if a.final_recommendation=="WATCH")
    sector_html="".join(f'<div class="sector"><strong>{escape(s)}</strong><div class="heat">{"●"*min(3,max(1,n))}</div><small>{n} changes · {sector_reviews[s]} review · {sector_watches[s]} watch</small></div>' for s,n in sector_counts.most_common()) or '<div class="empty">No sector activity yet.</div>'
    stats=scan_stats; health=f"{stats.sources_ok}/{stats.sources_configured} sources healthy" if stats else "source health unavailable"; raw=stats.raw_entries if stats else len(world_candidates); recent=stats.recent_entries if stats else len(world_candidates); matches=stats.structural_matches if stats else len(world_candidates)
    cards="".join(_assessment_card(c,a) for c,a in pairs) or '<div class="empty">No completed market-gap assessments yet.</div>'; pending="".join(_candidate_card(c) for c in unresolved[:24]) or '<div class="empty">All current leads have completed deep-dive.</div>'; verified="".join(_verified_card(e.verify()) for e in events) or '<div class="empty">No separate first-party events in the current window.</div>'
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GapRadar — Market Intelligence</title><style>{CSS}</style></head><body><main><div class="topbar"><div><div class="eyebrow">Continuous Market Intelligence</div><h1>GapRadar</h1><p class="lede">What changed in the world, which sectors are heating up, and where supply may not have caught up yet. Scans run every six hours; conclusions remain evidence- and coverage-bound.</p></div><div class="pulse">{escape(health)}</div></div><section class="metrics"><div class="metric"><strong>{review}</strong><span>review now</span></div><div class="metric"><strong>{watch}</strong><span>watch</span></div><div class="metric"><strong>{dismiss}</strong><span>likely served</span></div><div class="metric"><strong>{len(world_candidates)}</strong><span>structural changes</span></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">Priority 01</div><h2>Today’s market-gap recommendations</h2></div><p>Deep-dived results first. News never occupies the top of the product unless it has gone through market-supply analysis.</p></div><div class="grid">{cards}</div></section><section class="section"><div class="section-head"><div><div class="eyebrow">Priority 02</div><h2>Sector heat</h2></div><p>Activity is dynamic: attention follows structural change rather than giving every industry equal weight.</p></div><div class="sector-grid">{sector_html}</div></section><section class="section"><div class="section-head"><div><div class="eyebrow">Radar health</div><h2>Discovery funnel</h2></div><p>Zero recommendations can be a correct result. This funnel exposes whether the radar is healthy or source-degraded.</p></div><div class="funnel"><div class="step"><b>{raw}</b><span>raw items</span></div><div class="step"><b>{recent}</b><span>recent</span></div><div class="step"><b>{matches}</b><span>structural matches</span></div><div class="step"><b>{len(world_candidates)}</b><span>deduped leads</span></div><div class="step"><b>{len(pairs)}</b><span>deep-dived</span></div><div class="step"><b>{review}</b><span>review now</span></div></div></section><details><summary>Structural changes still under investigation ({len(unresolved)})</summary><div class="section"><div class="grid">{pending}</div></div></details><details><summary>Tier-1 verified changelog lane ({len(events)})</summary><div class="section"><div class="grid">{verified}</div></div></details><div class="footer">WORLD SCAN → STRUCTURAL CHANGE → DEMAND HYPOTHESIS → SUPPLY MAP → GAP ASSESSMENT → RECOMMENDATION. Reaction is supporting evidence, never a veto.</div></main></body></html>'''; output.write_text(html,encoding="utf-8")
